import importlib.util, importlib.machinery, random, json, math
loader = importlib.machinery.SourceFileLoader("runmod", "/app/submit/run")
spec = importlib.util.spec_from_loader("runmod", loader)
R = importlib.util.module_from_spec(spec); loader.exec_module(R)
FULL=(1<<128)-1
def trunc(v,b):
    if b<=0: return 0
    if b>=128: return v
    return v & (FULL ^ ((1<<(128-b))-1))
def al(x,k): return k*((x+k-1)//k)
def indep_cost(fib,b,e):
    if b==0:
        keys=[0]; d={0:fib}
    else:
        d={}
        for t in fib:
            v,l,h=t
            if l>b: d.setdefault(trunc(v,b),[]).append(t)
        keys=sorted(d)
    span=e-b; total=0
    for k in keys:
        pl=d[k]; rs=0; es=set()
        for (v,l,h) in pl:
            if l<=e: rs+=32+al(l-b,8)
            else: es.add(trunc(v,e))
        total+=al(128+rs+len(es)*(32+al(span,8)),64)
    return total
def rand_fib(rng,nmax=6):
    fib=[]; seen=set()
    for _ in range(rng.randint(0,nmax)):
        l=rng.choice([0,1,8,16,32,48,64,96,100,127,128,rng.randint(0,128)])
        v=trunc(rng.getrandbits(128),l)
        if (v,l) in seen: continue
        seen.add((v,l)); fib.append((v,l,rng.randint(0,65535)))
    return fib
def brute_opt(cost,caps,ms,S,depth_limit=[0]):
    best=[None]
    def rec(i,d,peak):
        if best[0] is not None and peak[0]*best[0][1] >= best[0][0]*peak[1]:
            pass
        if i==S:
            if d==128:
                if best[0] is None or peak[0]*best[0][1] < best[0][0]*peak[1]:
                    best[0]=peak
            return
        emax=min(d+ms,128)
        if (128-(emax))>(S-i-1)*ms: return
        for e in range(d+1,emax+1):
            if 128-e > (S-i-1)*ms: continue
            c=cost[(d,e)]
            b2=(c,caps[i])
            np = b2 if peak[0]*b2[1] < b2[0]*peak[1] else peak
            rec(i+1,e,np)
    rec(0,0,(0,1))
    return best[0]
def cnt_frac(a,b): return a[0]*b[1]-b[0]*a[1]
rng=random.Random(7)
issues=0; trials=0
for trial in range(400):
    fib=rand_fib(rng,5)
    S=rng.randint(4,5)
    base=(128+S-1)//S
    ms=rng.randint(base, base+4)
    caps=[rng.randint(300,4000) for _ in range(S)]
    cm=R.build_costmap(fib,ms)
    for _ in range(4):
        b=rng.randint(0,127); e=rng.randint(b+1,min(b+ms,128))
        if cm[(b,e)]!=indep_cost(fib,b,e):
            print("COSTMAP MISMATCH",trial,b,e); issues+=1
    res=R.solve_cuts(cm,caps,ms,S)
    bo=brute_opt(cm,caps,ms,S)
    trials+=1
    if res is None:
        if bo is not None:
            print("DP infeasible but brute feasible",trial); issues+=1
    else:
        cuts,frac=res
        st,used=R.build_stages(fib,cuts,ms)
        peak=R.max_ratio(used,caps)
        for i in range(S):
            if cm[(cuts[i],cuts[i+1])]!=used[i]:
                print("USED MISMATCH",trial,i); issues+=1
        if bo is None:
            print("DP feasible brute infeasible",trial); issues+=1
        elif cnt_frac(peak,bo)!=0:
            print("PEAK MISMATCH",trial,peak,bo,S,ms); issues+=1
print("done trials",trials,"issues",issues)
